// steps/support/td-resolve.ts
// Generated by QA-AI-Framework — Playwright Automation Agent
//
// Implements the "td.<column>" placeholder-resolution convention described in
// 03-standards/playwright-typescript-standards.md's Feature File Standards ("Step text
// placeholders in the form td.<column> are replaced at runtime from the resolved data
// row") for the STAFF/HARVEST/GUIDE clusters' own feature files/steps.
//
// IMPORTANT CONTEXT (flagged for the framework owner / other clusters): as of this
// generation, src/helper/hooks.ts and src/utils/CSVParser.ts do NOT implement this
// substitution anywhere — Cucumber passes a quoted Gherkin string straight through to the
// matching {string} parameter with no "td.*" rewriting. The AUTH/DASH/INVOICE/WAIVER
// clusters' steps files worked around this by avoiding "td.*" in Gherkin text entirely
// (reading this.testData directly in the step body instead). This module takes the other
// supported approach for this cluster: resolve "td.<column>" tokens against
// ScenarioContext.testData (the already-loaded CSV row) inside the step body itself,
// which keeps this cluster's feature files' "td.<column>" convention — matching the
// standard's own documented example and this cluster's original design — functionally
// correct without modifying any shared Framework scaffold file.
//
// Usage: replace `Given`/`When`/`Then` with `GivenR`/`WhenR`/`ThenR` from this module.
// Every {string}/{int}-captured argument is passed through `resolveTd()` before the real
// handler runs, so "td.ranchName" in a feature file resolves to
// `ScenarioContext.testData.ranchName` automatically; a value that does not start with
// "td." (e.g. a literal like "Deer" or "Active") passes through unchanged.

import { Given, When, Then } from '@cucumber/cucumber';
import { ScenarioContext } from '../../../Framework/src/utils/ScenarioContext';

export function resolveTd(ctx: ScenarioContext, value: unknown): unknown {
  if (typeof value !== 'string' || !value.startsWith('td.')) return value;
  const column = value.slice(3);
  const resolved = (ctx.testData as Record<string, unknown>)[column];
  return resolved !== undefined ? resolved : value;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type StepHandler = (this: ScenarioContext, ...args: any[]) => Promise<void> | void;

function resolveArgs(ctx: ScenarioContext, args: unknown[]): unknown[] {
  return args.map((a) => resolveTd(ctx, a));
}

// IMPORTANT: Cucumber validates a registered step function's arity against the pattern's
// placeholder count using the function's own `.length` (its declared parameter count).
// A wrapper written as `function (...args: unknown[]) {}` always has `.length === 0`
// regardless of how many placeholders the pattern actually has, which Cucumber rejects
// with "function has 0 arguments, should have N" for any pattern with 1+ placeholders.
// Fix: dynamically build a wrapper whose declared parameter count matches `handler.length`
// (TypeScript strips the `this` parameter at compile time, so handler.length already
// equals its real number of value arguments) using `new Function`, so Cucumber's arity
// check passes, while the generated function still just forwards to the real logic below.
function makeArityMatchedWrapper(
  arity: number,
  run: (self: ScenarioContext, args: unknown[]) => Promise<void> | void,
): (...args: unknown[]) => Promise<void> | void {
  const params = Array.from({ length: arity }, (_, i) => `a${i}`).join(', ');
  // eslint-disable-next-line @typescript-eslint/no-implied-eval, no-new-func
  const factory = new Function(
    'run',
    `return function (${params}) { return run(this, Array.prototype.slice.call(arguments)); };`,
  ) as (run: unknown) => (...args: unknown[]) => Promise<void> | void;
  return factory(run);
}

export function GivenR(pattern: string | RegExp, handler: StepHandler): void {
  const wrapper = makeArityMatchedWrapper(handler.length, async (self, args) => {
    await handler.apply(self, resolveArgs(self, args));
  });
  Given(pattern, wrapper);
}

export function WhenR(pattern: string | RegExp, handler: StepHandler): void {
  const wrapper = makeArityMatchedWrapper(handler.length, async (self, args) => {
    await handler.apply(self, resolveArgs(self, args));
  });
  When(pattern, wrapper);
}

export function ThenR(pattern: string | RegExp, handler: StepHandler): void {
  const wrapper = makeArityMatchedWrapper(handler.length, async (self, args) => {
    await handler.apply(self, resolveArgs(self, args));
  });
  Then(pattern, wrapper);
}
